describe('Notification Message Rendered', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/notification_message_rendered');
  });

  it('should display notification with success or unsuccessful message when clicking the link', () => {
    cy.get('a').contains('Click here').click();

    cy.get('#flash', { timeout: 5000 }).should('be.visible');

    cy.get('#flash').then(($flash) => {
      const flashText = $flash.text();
      expect(flashText).to.match(/Action successful|Action unsuccessful/);
    });
  });

  it('should dismiss notification when clicking the close icon', () => {
    cy.get('a').contains('Click here').click();

    cy.get('#flash', { timeout: 5000 }).should('be.visible');

    cy.get('#flash .close').should('be.visible').click();

    cy.get('#flash').should('not.be.visible');
  });

  it('should handle multiple notification cycles', () => {
    // First notification
    cy.get('a').contains('Click here').click();
    cy.get('#flash', { timeout: 5000 }).should('be.visible');
    cy.get('#flash').invoke('text').should('match', /Action successful|Action unsuccessful/);

    // Dismiss first notification
    cy.get('#flash .close').click();
    cy.get('#flash').should('not.be.visible');

    // Second notification
    cy.get('a').contains('Click here').click();
    cy.get('#flash', { timeout: 5000 }).should('be.visible');
    cy.get('#flash').invoke('text').should('match', /Action successful|Action unsuccessful/);

    // Dismiss second notification
    cy.get('#flash .close').click();
    cy.get('#flash').should('not.be.visible');
  });

  it('should verify flash element contains expected text variations', () => {
    cy.get('a').contains('Click here').click();

    cy.get('#flash', { timeout: 5000 })
      .should('be.visible')
      .and(($flash) => {
        const text = $flash.text();
        const isSuccessful = text.includes('Action successful');
        const isUnsuccessful = text.includes('Action unsuccessful');
        expect(isSuccessful || isUnsuccessful).to.be.true;
      });
  });
});
